// returns 1*1 + 2*2 + ... + n*n
unsigned int sum_squares(unsigned int n) {
    unsigned int total = 0;         // running total starts at 0
    for (unsigned int i = 1; i <= n; i++) {
        total = total + i * i;
    }
    return total;
}

// returns 1/1 + 1/2 + ... + 1/n
double harmonic(unsigned int n) {
    double total = 0.0;
    for (unsigned int k = 1; k <= n; k++) {
        total = total + 1.0 / k;    // 1.0 makes this double division
    }
    return total;
}

