#include <math.h>
#include <stdio.h>

// returns 1 - 1/2 + 1/3 - 1/4 + ... (n terms)
double alt_harmonic(unsigned int n) {
    double total = 0.0;
    double sign = 1.0;              // +1.0 for the first term
    for (unsigned int k = 1; k <= n; k++) {
        total = total + sign / k;
        sign = -sign;               // flip: +, -, +, -, ...
    }
    return total;
}

int main(void) {
    printf("%24.17f\n", alt_harmonic(10));
    printf("%24.17f\n", alt_harmonic(1000));
    printf("%24.17f\n", log(2.0));  // the exact limit is ln 2
    return 0;
}

#include <math.h>
#include <stdio.h>
#include <stdlib.h>

// approximates e to the power x with the terms x^0/0! up to x^last/last!
double my_exp(double x, int last) {
    double term = 1.0;      // the n = 0 term: x^0 / 0! = 1
    double total = term;
    for (int n = 1; n <= last; n++) {
        term = term * x / n;    // turns x^(n-1)/(n-1)! into x^n/n!
        total = total + term;
    }
    return total;
}

int main(void) {
    double x = 1.0;
    printf("%24.17f  (4 terms)\n", my_exp(x, 3));
    printf("%24.17f  (11 terms)\n", my_exp(x, 10));
    printf("%24.17f  (21 terms)\n", my_exp(x, 20));
    printf("%24.17f  (library exp)\n", exp(x));
    return 0;
}

