#include <stdio.h>

// returns 1 - 1/4 + 1/9 - 1/16 + ... (n terms)
double alt_squares(unsigned int n) {
    double total = 0.0;
    double sign = 1.0;
    for (unsigned int k = 1; k <= n; k++) {
        total = total + sign / ((double) k * k);
        sign = -sign;
    }
    return total;
}

int main(void) {
    printf("%.6f\n", alt_squares(1));
    printf("%.6f\n", alt_squares(2));
    printf("%.6f\n", alt_squares(3));
    return 0;
}

